(()=>{
  'use strict';

  const root=document.querySelector('[data-oms-v1]'),ownerAPI=globalThis.OMSPhase1OwnerAPI,model=globalThis.OMSInternalModel;
  if(!root||!model||!ownerAPI?.app?.('internal-finance-requests'))return;

  const identityRoute=String(root.dataset.identityRoutePrefix||'').replace(/\/$/,'');
  const safe=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const uuid=()=>globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,value=>{const random=Math.random()*16|0,part=value==='x'?random:(random&3|8);return part.toString(16)});
  const today=()=>{const value=new Date();return new Date(value.getTime()-value.getTimezoneOffset()*60000).toISOString().slice(0,10)};
  const date=value=>value?String(value).slice(0,10).replaceAll('-','/'):'—';
  const dateTime=value=>{if(!value)return '—';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?String(value):new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(parsed)};
  const option=(value,label,current)=>'<option value="'+safe(value)+'" '+(String(value)===String(current)?'selected':'')+'>'+safe(label)+'</option>';
  const field=(label,control,wide=false)=>'<label class="oms-v1__form-field'+(wide?' is-wide':'')+'"><span>'+safe(label)+'</span>'+control+'</label>';
  const formStatus=copy=>'<div class="oms-v1__form-status is-wide" data-oms-v1-form-status>'+safe(copy||'')+'</div>';
  const tag=(label,tone='')=>'<span class="oms-v1__internal-tag '+(tone?'is-'+tone:'')+'">'+safe(label)+'</span>';
  const show=detail=>root.dispatchEvent(new CustomEvent('oms-v1:show-dialog',{detail}));
  const close=()=>root.dispatchEvent(new CustomEvent('oms-v1:close-dialog'));
  const api=(path,options)=>ownerAPI.api('internal-finance-requests',path,options);
  const post=(path,value)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
  const put=(path,value)=>api(path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
  const del=(path,value)=>api(path,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
  const identityAPI=async path=>{const response=await fetch(identityRoute+path,{headers:{Accept:'application/json'},credentials:'same-origin',cache:'no-store',redirect:'error'});if(!response.ok)throw new Error('账号目录暂不可用');return response.json()};
  const minorJSON=value=>{const amount=model.decimalMinor(value);if(amount===null||amount<=0n||amount>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('金额必须大于 0、最多两位小数且不能超出安全范围');return Number(amount)};
  const minorInput=value=>{try{const raw=BigInt(String(value||0)),whole=raw/100n,fraction=String(raw%100n).padStart(2,'0');return String(whole)+'.'+fraction}catch{return '0.00'}};
  const statusLabels={draft:'草稿',payable:'待支付',partially_paid:'部分支付',paid:'已支付',paid_with_overpayment:'超额异常',withdrawn:'已撤回'};
  const typeLabels={reimbursement:'报销',payment:'付款申请'};
  const tone=value=>value==='paid'?'positive':value==='payable'||value==='partially_paid'?'warning':value==='withdrawn'?'muted':value==='paid_with_overpayment'?'warning':'';
  const allowed=(item,action)=>(item?.allowed_actions||[]).includes(action);
  const hasEvidence=item=>Boolean(item?.details?.evidence?.length||item?.details?.lines?.some(line=>line.evidence?.length));
  const hasEnteredPayable=item=>['payable','partially_paid','paid','paid_with_overpayment'].includes(item?.status);
  const isRevisionConflict=error=>/revision conflict/i.test(String(error instanceof Error?error.message:error||''));
  const paymentSelectable=item=>allowed(item,'confirm_payment')&&(item.status==='payable'||item.status==='partially_paid')&&Number(item.payment_unknown_count||0)===0;
  const duplicateIDs=item=>item?.details?.duplicate?.status==='strong'&&Array.isArray(item.details.duplicate.matched_request_ids)?item.details.duplicate.matched_request_ids.filter(id=>id&&id!==item.id):[];
  const duplicateConflict=item=>duplicateIDs(item).length>0;
  const duplicateTarget=item=>duplicateIDs(item).map(id=>state.conflictTargets.get(id)||state.items.find(value=>value.id===id)).find(Boolean)||null;
  const duplicateSummary=item=>{const ids=duplicateIDs(item),targets=ids.map(id=>state.conflictTargets.get(id)||state.items.find(value=>value.id===id)).filter(Boolean);if(targets.length)return '发票已被'+targets.map(target=>(typeLabels[target.request_type]||'财务申请')+'「'+target.title+'」（'+(statusLabels[target.status]||target.status)+'）').join('、')+'占用';return ids.length?'发票已被其他财务申请占用（引用 '+ids.map(id=>String(id).slice(0,8)).join('、')+'）':''};
  const submitSelectable=item=>allowed(item,'submit')&&(item.status==='draft'||item.status==='withdrawn')&&(item.request_type!=='reimbursement'||hasEvidence(item))&&!duplicateConflict(item);
  const batchKind=item=>paymentSelectable(item)?'payment':submitSelectable(item)?'submit':'';
  const selectedBatchKind=()=>{const kinds=new Set([...state.selected].map(id=>batchKind(state.items.find(item=>item.id===id))).filter(Boolean));return kinds.size===1?[...kinds][0]:''};
  const selectionReason=item=>batchKind(item)?'':duplicateConflict(item)?duplicateSummary(item):item.request_type==='reimbursement'&&(item.status==='draft'||item.status==='withdrawn')&&!hasEvidence(item)?'报销草稿需先补充发票或有效凭证':'当前状态暂无可用的批量操作';
  const remaining=item=>BigInt(String(item.amount_minor||0))-BigInt(String(item.allocated_minor||0));
  const hashSnapshot=async value=>{if(!globalThis.crypto?.subtle)throw new Error('浏览器不支持安全摘要，不能提交正式申请');const raw=new TextEncoder().encode(JSON.stringify(value)),digest=new Uint8Array(await crypto.subtle.digest('SHA-256',raw));return 'sha256:'+Array.from(digest,byte=>byte.toString(16).padStart(2,'0')).join('')};

  const state={items:[],categories:[],parties:[],people:[],groups:[],projects:[],contracts:[],actors:new Map(),conflictTargets:new Map(),applicant:null,selected:new Set(),page:1,pageSize:20,sort:{key:'updated_at',direction:'desc'},loading:true,error:''};

  const actorLabel=value=>{const id=String(value||'');if(!id)return '—';const displayName=state.actors.get(id)||(id===String(root.dataset.subjectId||'')?String(root.dataset.displayName||''):'');return displayName||'账号 '+id.slice(0,8)};

  function flattenProjects(items){const result=[];for(const item of items||[]){result.push(item);result.push(...flattenProjects(item.children||[]))}return result}
  function projectContracts(projects){const seen=new Set(),result=[];for(const project of projects){for(const link of project.resource_links||[]){if(link.target_service!=='contract-ledger'||link.resource_type!=='contract'||!link.source_revision||seen.has(link.resource_id))continue;seen.add(link.resource_id);result.push({id:link.resource_id,revision:Number(link.source_revision),name:link.note||project.name+' · 合同'})}}return result}

  async function hydrateConflictTargets(ids){
    const unique=[...new Set((ids||[]).filter(Boolean))],missing=unique.filter(id=>!state.conflictTargets.has(id));
    if(!missing.length)return;
    const results=await Promise.allSettled(missing.map(id=>api('/api/v1/finance-requests/'+encodeURIComponent(id))));
    results.forEach((result,index)=>{if(result.status==='fulfilled')state.conflictTargets.set(missing[index],result.value)});
  }

  async function rememberStrongDuplicate(item,error){
    const ids=Array.isArray(error?.data?.matched_request_ids)?error.data.matched_request_ids.filter(Boolean):[];
    item.details=item.details||{};item.details.duplicate={status:'strong',matched_request_ids:ids,checked_at:new Date().toISOString()};
    if(!state.items.some(value=>value.id===item.id))state.items.unshift(item);
    state.conflictTargets.set(item.id,item);
    await hydrateConflictTargets(ids);render();
    return duplicateSummary(item)||error?.message||'发票已被其他财务申请占用';
  }

  function openDuplicateResolution(item){
    const target=duplicateTarget(item),summary=duplicateSummary(item)||'该发票已经上传并用于其他财务申请';
    show({kicker:'重复发票阻断',title:'这张发票已经使用过',dismissOnly:true,body:'<section class="oms-v1__invoice-use"><div class="oms-v1__finance-conflict-panel"><strong>不能覆盖或再次提交</strong><span>'+safe(summary)+'</span></div><p>系统已停止本次提交。已提交记录不能被新草稿覆盖；请选择查看原申请、修改并更换当前草稿的发票，或删除当前草稿。</p><div class="oms-v1__invoice-use-actions">'+(target?'<button type="button" data-duplicate-view><strong>查看原申请</strong><span>核对原申请的状态、金额和发票</span></button>':'')+'<button type="button" data-duplicate-edit><strong>修改／更换发票</strong><span>返回当前草稿，重新上传正确原件</span></button>'+(allowed(item,'delete')?'<button type="button" class="is-danger" data-duplicate-delete><strong>删除当前草稿</strong><span>填写删除原因后从默认列表隐藏</span></button>':'')+'</div><p>如果原申请本身有误，请进入原申请撤回并沿原 revision 链纠正；删除当前草稿不会改写原申请。</p></section>'});
    queueMicrotask(()=>{root.querySelector('[data-duplicate-view]')?.addEventListener('click',()=>openDetail(target));root.querySelector('[data-duplicate-edit]')?.addEventListener('click',()=>openEditor(item));root.querySelector('[data-duplicate-delete]')?.addEventListener('click',()=>openDelete(item))});
  }

  async function load(){
    state.loading=true;state.error='';render();
    const tasks=await Promise.allSettled([
      api('/api/v1/finance-requests'),
      api('/api/v1/expense-categories'),
      ownerAPI.app('people-groups')?ownerAPI.api('people-groups','/api/v1/references/iam-subjects/'+encodeURIComponent(root.dataset.subjectId)+'/person'):Promise.reject(new Error('成员服务未装配')),
      ownerAPI.app('party-directory')?ownerAPI.api('party-directory','/api/v1/parties?status=active&limit=200'):Promise.resolve({items:[]}),
      ownerAPI.app('people-groups')?ownerAPI.api('people-groups','/api/v1/persons'):Promise.resolve([]),
      ownerAPI.app('people-groups')?ownerAPI.api('people-groups','/api/v1/groups'):Promise.resolve([]),
      ownerAPI.app('project-workspace')?ownerAPI.api('project-workspace','/api/v1/project-directory?limit=100&status=all'):Promise.resolve({items:[]}),
      root.dataset.administrator==='true'?identityAPI('/api/v1/admin/subjects'):Promise.resolve({subjects:[]}),
    ]);
    if(tasks[0].status==='fulfilled')state.items=Array.isArray(tasks[0].value?.items)?tasks[0].value.items:[];else{state.items=[];state.error=tasks[0].reason instanceof Error?tasks[0].reason.message:'财务数据暂不可用'}
    state.conflictTargets=new Map(state.items.map(item=>[item.id,item]));
    await hydrateConflictTargets(state.items.flatMap(duplicateIDs));
    state.categories=tasks[1].status==='fulfilled'&&Array.isArray(tasks[1].value?.items)?tasks[1].value.items:[];
    state.applicant=tasks[2].status==='fulfilled'?tasks[2].value:null;
    state.parties=tasks[3].status==='fulfilled'&&Array.isArray(tasks[3].value?.items)?tasks[3].value.items:[];
    state.people=tasks[4].status==='fulfilled'&&Array.isArray(tasks[4].value)?tasks[4].value.filter(item=>item.status==='active'):[];
    if(state.applicant&&!state.people.some(item=>item.id===state.applicant.id))state.people.unshift(state.applicant);
    state.groups=tasks[5].status==='fulfilled'&&Array.isArray(tasks[5].value)?tasks[5].value.filter(item=>item.status==='active'):[];
    state.projects=tasks[6].status==='fulfilled'?flattenProjects(tasks[6].value?.items||[]).filter(item=>item.status!=='archived'):[];
    state.actors.clear();
    if(root.dataset.subjectId&&root.dataset.displayName)state.actors.set(String(root.dataset.subjectId),String(root.dataset.displayName));
    if(tasks[7].status==='fulfilled')for(const subject of tasks[7].value?.subjects||[])if(subject?.id&&subject?.display_name)state.actors.set(String(subject.id),String(subject.display_name));
    state.contracts=projectContracts(state.projects);
    state.loading=false;render();
  }

  function filtered(source=state.items){
    const search=root.querySelector('[data-internal-finance-search]').value.trim().toLowerCase(),type=root.querySelector('[data-internal-finance-type]').value,status=root.querySelector('[data-internal-finance-status]').value;
    const values=source.filter(item=>(!search||[item.title,item.details?.applicant?.display_name,item.details?.payee?.display_name,actorLabel(item.payments?.at(-1)?.operator_subject_id||item.applicant_subject_id)].some(value=>String(value||'').toLowerCase().includes(search)))&&(!type||item.request_type===type)&&(!status||item.status===status));
    return values.sort((left,right)=>{const key=state.sort.key,a=key==='amount'?BigInt(String(left.amount_minor||0)):key==='type'?left.request_type:key==='business_date'?left.details?.lines?.[0]?.business_date:left[key]||'',b=key==='amount'?BigInt(String(right.amount_minor||0)):key==='type'?right.request_type:key==='business_date'?right.details?.lines?.[0]?.business_date:right[key]||'',result=typeof a==='bigint'?(a===b?0:a>b?1:-1):String(a).localeCompare(String(b),'zh-CN',{numeric:true});return state.sort.direction==='asc'?result:-result});
  }

  function renderPager(total){
    const target=root.querySelector('[data-internal-pager="finance"]'),pages=Math.max(1,Math.ceil(total/state.pageSize));state.page=Math.min(state.page,pages);
    target.innerHTML='<span>第 '+state.page+' / '+pages+' 页</span><div><button type="button" data-prev '+(state.page<=1?'disabled':'')+'>‹</button><button type="button" class="is-current">'+state.page+'</button><button type="button" data-next '+(state.page>=pages?'disabled':'')+'>›</button></div><select aria-label="每页数量"><option value="20" '+(state.pageSize===20?'selected':'')+'>20 条/页</option><option value="50" '+(state.pageSize===50?'selected':'')+'>50 条/页</option><option value="100" '+(state.pageSize===100?'selected':'')+'>100 条/页</option></select>';
    target.querySelector('[data-prev]').onclick=()=>{state.page--;render()};target.querySelector('[data-next]').onclick=()=>{state.page++;render()};target.querySelector('select').onchange=event=>{state.pageSize=Number(event.target.value)||20;state.page=1;render()};
    return {start:(state.page-1)*state.pageSize,end:state.page*state.pageSize};
  }

  function render(){
    const body=root.querySelector('[data-internal-finance-body]'),items=filtered(),range=renderPager(items.length);root.querySelector('[data-internal-finance-total]').textContent=String(items.length);
    if(state.loading)body.innerHTML=empty('正在读取财务申请','请稍候');
    else if(state.error)body.innerHTML=empty('财务申请暂不可用',state.error);
    else {const mode=selectedBatchKind();body.innerHTML=items.length?items.slice(range.start,range.end).map(item=>{const kind=batchKind(item),disabled=!kind||Boolean(mode&&kind!==mode),reason=selectionReason(item),target=duplicateTarget(item),conflict=duplicateSummary(item);return '<tr><td><input type="checkbox" data-finance-owner-select="'+item.id+'" data-finance-owner-kind="'+safe(kind)+'" '+(disabled?'disabled':'')+' '+(state.selected.has(item.id)?'checked':'')+' aria-label="选择 '+safe(item.title)+'" title="'+safe(reason||'选择后进行'+(kind==='submit'?'进入待支付':'付款确认'))+'"></td><td>'+tag(typeLabels[item.request_type]||item.request_type)+'</td><td><strong title="'+safe(item.title)+'">'+safe(item.title)+'</strong></td><td>'+safe(item.details?.applicant?.display_name||'—')+'</td><td>'+safe(item.details?.payee?.display_name||'—')+(item.details?.payee?.account_last4?' · 尾号 '+safe(item.details.payee.account_last4):'')+'</td><td class="is-number is-money">'+model.money(item.amount_minor)+'</td><td>'+date(item.details?.lines?.[0]?.business_date)+'</td><td>'+tag(statusLabels[item.status]||item.status,tone(item.status))+(item.payment_unknown_count?'<small> 结果待核对</small>':'')+(conflict?'<small class="oms-v1__finance-conflict">'+safe(conflict)+'</small>':'')+'</td><td>'+safe(actorLabel(item.payments?.at(-1)?.operator_subject_id||item.applicant_subject_id))+'</td><td><span class="oms-v1__row-actions"><button type="button" data-finance-owner-detail="'+item.id+'">详情</button>'+(allowed(item,'update')?'<button type="button" data-finance-owner-edit="'+item.id+'">编辑</button>':'')+(target?'<button type="button" data-finance-owner-conflict="'+target.id+'">查看占用申请</button>':'')+(submitSelectable(item)?'<button type="button" data-finance-owner-submit="'+item.id+'">进入待支付</button>':'')+(allowed(item,'withdraw')?'<button type="button" data-finance-owner-withdraw="'+item.id+'">撤回</button>':'')+(allowed(item,'delete')?'<button type="button" class="is-danger" data-finance-owner-delete="'+item.id+'">删除草稿</button>':'')+'</span></td></tr>'}).join(''):empty('暂无财务申请','新增报销或付款申请后，正式数据会保存在财务申请服务。');}
    for(const box of body.querySelectorAll('[data-finance-owner-select]'))box.onchange=()=>{box.checked?state.selected.add(box.dataset.financeOwnerSelect):state.selected.delete(box.dataset.financeOwnerSelect);syncBatch(items)};
    for(const button of body.querySelectorAll('[data-finance-owner-detail]'))button.onclick=()=>openDetail(state.items.find(item=>item.id===button.dataset.financeOwnerDetail));
    for(const button of body.querySelectorAll('[data-finance-owner-edit]'))button.onclick=()=>openEditor(state.items.find(item=>item.id===button.dataset.financeOwnerEdit));
    for(const button of body.querySelectorAll('[data-finance-owner-conflict]'))button.onclick=()=>openDetail(state.conflictTargets.get(button.dataset.financeOwnerConflict)||state.items.find(item=>item.id===button.dataset.financeOwnerConflict));
    for(const button of body.querySelectorAll('[data-finance-owner-submit]'))button.onclick=()=>openSubmit([state.items.find(item=>item.id===button.dataset.financeOwnerSubmit)]);
    for(const button of body.querySelectorAll('[data-finance-owner-withdraw]'))button.onclick=()=>openWithdraw(state.items.find(item=>item.id===button.dataset.financeOwnerWithdraw));
    for(const button of body.querySelectorAll('[data-finance-owner-delete]'))button.onclick=()=>openDelete(state.items.find(item=>item.id===button.dataset.financeOwnerDelete));
    for(const button of root.querySelectorAll('[data-internal-sort="finance"]')){const active=state.sort.key===button.dataset.key;button.classList.toggle('is-active',active);button.dataset.sortDirection=active?state.sort.direction:'';button.onclick=()=>{state.sort={key:button.dataset.key,direction:active&&state.sort.direction==='asc'?'desc':'asc'};render()}}
    syncBatch(items);
  }
  function empty(title,copy){return '<tr><td colspan="10"><div class="oms-v1__empty"><strong>'+safe(title)+'</strong><span>'+safe(copy)+'</span></div></td></tr>'}
  function syncBatch(items){let mode=selectedBatchKind();const visible=new Set(items.filter(item=>batchKind(item)&&(!mode||batchKind(item)===mode)).map(item=>item.id));for(const id of state.selected)if(!visible.has(id))state.selected.delete(id);mode=selectedBatchKind();const kinds=new Set(items.map(batchKind).filter(Boolean)),active=mode||(kinds.size===1?[...kinds][0]:'');for(const box of root.querySelectorAll('[data-finance-owner-select]')){const item=state.items.find(value=>value.id===box.dataset.financeOwnerSelect),kind=batchKind(item);box.disabled=!kind||Boolean(mode&&kind!==mode);box.title=selectionReason(item)||(mode&&kind!==mode?'请先完成当前已选记录的'+(mode==='submit'?'进入待支付':'付款确认'):'选择后进行'+(kind==='submit'?'进入待支付':'付款确认'))}const bar=root.querySelector('[data-internal-finance-batch]'),action=bar.querySelector('[data-internal-finance-paid]');bar.querySelector('strong').textContent=String(state.selected.size);bar.querySelector('[data-internal-finance-select-all]').disabled=!items.some(item=>batchKind(item)&&(!mode||batchKind(item)===mode)&&!state.selected.has(item.id));bar.querySelector('[data-internal-finance-clear]').disabled=state.selected.size===0;action.textContent=active==='submit'?'进入待支付':active==='payment'?'确认已支付':'选择后操作';action.disabled=state.selected.size===0;action.dataset.financeBatchAction=mode}

  function draftValue(draft,key,fallback=''){return draft&&draft[key]!==undefined?draft[key]:fallback}
  function draftFromItem(item,draft=null){if(draft||!item)return draft;const line=item.details?.lines?.[0]||{},invoice=line.invoice||null;return {title:item.title||line.purpose||'',amount:minorInput(line.amount_minor||item.amount_minor),business_date:line.business_date||today(),invoice_mode:invoice?'manual':'none',invoice_code:invoice?.code||'',invoice_number:invoice?.number||'',invoice_date:invoice?.invoice_date||'',invoice_issuer_name:invoice?.issuer_name||'',invoice_amount:minorInput(invoice?.amount_minor||line.amount_minor||item.amount_minor),save_mode:'draft',notice:duplicateConflict(item)?'该发票已被其他申请使用，请更换正确发票或删除当前草稿。':''}}
  function invoiceEntryMarkup(draft={},recognized=null,requestType='payment'){
    const reimbursement=requestType==='reimbursement',requestLabel=reimbursement?'报销':'付款',candidate=recognized?.candidate||{},mode=recognized?'recognition':draftValue(draft,'invoice_mode','none'),amount=draftValue(draft,'invoice_amount',minorInput(candidate.total_amount_minor)),dateValue=draftValue(draft,'invoice_date',candidate.issued_on||''),issuer=draftValue(draft,'invoice_issuer_name',candidate.seller_name||''),code=draftValue(draft,'invoice_code',candidate.invoice_code||''),number=draftValue(draft,'invoice_number',candidate.invoice_number||'');
    return '<section class="oms-v1__finance-invoice is-wide" data-finance-invoice-entry><input type="file" hidden data-finance-recognition-file accept=".pdf,.ofd,.xml,.png,.jpg,.jpeg,application/pdf,image/png,image/jpeg,application/xml,text/xml"><header><div><span>发票优先录入</span><strong>上传发票，自动填写基本信息</strong><small>识别后逐项核对，再回到当前'+requestLabel+'申请</small></div><div class="oms-v1__finance-invoice-primary"><button type="button" data-finance-recognize>'+(recognized?'重新上传识别':'上传发票并识别')+'</button><small>支持图片、PDF、OFD、XML</small></div></header><div class="oms-v1__finance-invoice-methods">'
      +[['none','暂不录入',reimbursement?'仅保存草稿，提交前补充':'稍后补充或本次无需发票'],['manual','直接录入','手工填写票面并上传原票'],['recognition','上传并识别','识别原票后逐项人工确认']].map(value=>'<label><input type="radio" name="invoice_mode" value="'+value[0]+'" '+(mode===value[0]?'checked':'')+'><span><strong>'+value[1]+'</strong><small>'+value[2]+'</small></span></label>').join('')+'</div>'
      +'<div class="oms-v1__form-grid oms-v1__finance-invoice-panel" data-finance-invoice-panel="manual">'+field('发票号码 *','<input name="invoice_number" maxlength="64" value="'+safe(number)+'">')+field('开票日期 *','<input name="invoice_date" type="date" value="'+safe(dateValue)+'">')+field('销售方 *','<input name="invoice_issuer_name" maxlength="200" value="'+safe(issuer)+'">')+field('价税合计（元） *','<input name="invoice_amount" inputmode="decimal" value="'+safe(amount)+'">')+field(reimbursement?'原发票文件（提交报销时必需）':'原发票文件（建议上传）','<input name="finance_invoice_file" type="file" accept=".pdf,.ofd,.xml,.png,.jpg,.jpeg,application/pdf,image/png,image/jpeg,application/xml,text/xml">')+field('发票代码（选填）','<input name="invoice_code" maxlength="64" value="'+safe(code)+'" placeholder="仅旧版发票有此字段">')+'</div>'
      +'<div class="oms-v1__finance-invoice-panel" data-finance-invoice-panel="recognition">'+(recognized?'<div class="oms-v1__finance-recognition-summary"><span>已确认并关联当前申请</span><strong>'+safe(candidate.invoice_number||'待补充号码')+' · '+safe(issuer||'销售方待补充')+'</strong><small>'+safe(dateValue||'日期待补充')+' · '+safe(amount||'0.00')+' 元 · Evidence v'+safe(recognized.evidence?.version||'—')+'</small></div>':'<div class="oms-v1__finance-recognition-empty"><strong>等待选择发票</strong><span>点击上方“上传发票并识别”，确认后自动填入金额、日期、销售方和发票号码。</span></div>')+'</div>'
      +'<p>识别确认只用于当前这笔新'+requestLabel+'申请；不会自动登记项目进项／销项票据，也不会进入外部业务。</p></section>';
  }
  function editorBody(item,type,draft=null,recognized=null){
    const details=item?.details||{},line=details.lines?.[0]||{},payment=type==='payment',payee=details.payee||{},copy=payment?'付款说明':'报销内容';
    return '<form class="oms-v1__form-grid" data-finance-request-type="'+safe(type)+'" data-line-id="'+safe(line.id||'')+'">'
      +invoiceEntryMarkup(draft||{},recognized,type)
      +'<div class="oms-v1__form-section-heading is-wide"><span>基本信息</span><strong>填写'+copy+'、金额和日期</strong></div>'
      +field(copy+' *','<input name="title" required maxlength="200" value="'+safe(draftValue(draft,'title',item?.title||line.purpose||''))+'">',true)
      +field('金额（元） *','<input name="amount" required inputmode="decimal" value="'+safe(draftValue(draft,'amount',minorInput(line.amount_minor||item?.amount_minor)))+'">')
      +field('日期 *','<input name="business_date" type="date" required value="'+safe(draftValue(draft,'business_date',line.business_date||today()))+'">')
      +(payment?payeeMarkup(payee,draft):'')
      +field('保存方式','<select name="save_mode">'+option('draft','保存草稿',draftValue(draft,'save_mode','draft'))+option('submit','保存并提交',draftValue(draft,'save_mode',item?.status==='withdrawn'?'submit':''))+'</select>')
      +'<div class="oms-v1__form-note is-wide">'+(payment?'付款申请保存付款方式和收款账户快照；实际付款仍需在系统中单独确认。':'发票在草稿阶段可不上传；正式提交前必须补充至少一份发票或其他有效凭证。')+'</div>'
      +formStatus(draftValue(draft,'notice',state.applicant?'':'当前账号尚未匹配成员档案，不能创建正式申请'))+'</form>';
  }
  function payeeMarkup(payee={},draft=null){const source=draftValue(draft,'payee_source',payee.kind==='party'?'party':'one_time'),method=draftValue(draft,'payment_method',payee.payment_method||'bank_transfer');return '<div class="oms-v1__form-grid is-wide" data-finance-payee-fields>'
    +field('付款方式 *','<select name="payment_method">'+option('cash','现金',method)+option('bank_transfer','银行卡',method)+'</select>')
    +field('收款方来源 *','<select name="payee_source">'+option('party','主体库',source)+option('one_time','一次性收款方',source)+'</select>')
    +field('主体库收款方','<select name="party_id"><option value="">请选择主体</option>'+state.parties.map(item=>option(item.id,item.legal_name,draftValue(draft,'party_id',payee.reference?.id))).join('')+'</select>')
    +field('收款方名称 *','<input name="payee_name" required maxlength="200" value="'+safe(draftValue(draft,'payee_name',payee.display_name||''))+'">')
    +'<div class="oms-v1__form-grid is-wide" data-payment-bank-fields>'
    +field('开户行 *','<input name="bank_name" maxlength="200" value="'+safe(draftValue(draft,'bank_name',payee.bank_name||''))+'">')
    +field('银行账户 *','<input name="account_number" autocomplete="off" value="'+safe(draftValue(draft,'account_number',''))+'" placeholder="'+(payee.account_last4?'请重新输入尾号 '+safe(payee.account_last4)+' 的完整账号':'请输入银行账户')+'">')+'</div></div>'}

  function financeDraft(form){const value=name=>form.querySelector('[name="'+name+'"]')?.value||'';return {title:value('title'),amount:value('amount'),business_date:value('business_date'),payment_method:value('payment_method'),payee_source:value('payee_source'),party_id:value('party_id'),payee_name:value('payee_name'),bank_name:value('bank_name'),account_number:value('account_number'),invoice_mode:form.querySelector('[name="invoice_mode"]:checked')?.value||'none',invoice_code:value('invoice_code'),invoice_number:value('invoice_number'),invoice_date:value('invoice_date'),invoice_issuer_name:value('invoice_issuer_name'),invoice_amount:value('invoice_amount'),save_mode:value('save_mode')}}
  function financeEvidenceRef(ref){return {file_id:String(ref?.file_id||''),version:Number(ref?.version||0),purpose:'invoice',sha256:String(ref?.content_sha256||ref?.sha256||'').replace(/^sha256:/,''),media_type:String(ref?.mime_type||ref?.media_type||''),size_bytes:Number(ref?.size_bytes||0)}}
  function bindEditorControls(item=null,type='reimbursement',draft=null,recognized=null){
    const form=root.querySelector('[data-oms-v1-dialog-body] form');if(!form)return;
    const method=form.querySelector('[name="payment_method"]'),bank=form.querySelector('[data-payment-bank-fields]'),source=form.querySelector('[name="payee_source"]'),party=form.querySelector('[name="party_id"]'),name=form.querySelector('[name="payee_name"]');
    const syncBank=()=>{const required=method.value==='bank_transfer';bank.hidden=!required;for(const input of bank.querySelectorAll('input'))input.required=required};
    const syncPayee=()=>{if(!source||!party||!name)return;const fromParty=source.value==='party';party.required=fromParty;party.disabled=!fromParty;name.required=!fromParty;name.disabled=fromParty;if(fromParty){const selected=state.parties.find(value=>value.id===party.value);name.value=selected?.legal_name||''}};
    const syncInvoice=()=>{const mode=form.querySelector('[name="invoice_mode"]:checked')?.value||'none';for(const panel of form.querySelectorAll('[data-finance-invoice-panel]')){const active=panel.dataset.financeInvoicePanel===mode;panel.hidden=!active;for(const input of panel.querySelectorAll('input:not([type="file"])'))input.required=active&&mode==='manual'}};
    if(method&&bank){method.onchange=syncBank;syncBank()}
    if(source&&party&&name){source.onchange=syncPayee;party.onchange=syncPayee;syncPayee()}
    for(const radio of form.querySelectorAll('[name="invoice_mode"]'))radio.onchange=syncInvoice;
    const recognitionInput=form.querySelector('[data-finance-recognition-file]'),recognizeButtons=form.querySelectorAll('[data-finance-recognize]');
    if(recognitionInput&&recognizeButtons.length){for(const button of recognizeButtons)button.onclick=()=>{const mode=form.querySelector('[name="invoice_mode"][value="recognition"]');if(mode){mode.checked=true;syncInvoice()}recognitionInput.click()};recognitionInput.onchange=async()=>{const file=recognitionInput.files?.[0],savedDraft=financeDraft(form),requestLabel=type==='reimbursement'?'报销':'付款';recognitionInput.value='';if(!file)return;const bridge=globalThis.OMSInvoiceRecognitionBridge,recognize=bridge?.recognizeForFinance||bridge?.recognizeForPayment;if(!recognize){savedDraft.notice='发票识别能力尚未就绪，请刷新页面后重试';openEditor(item,type,savedDraft,recognized);return}try{await recognize.call(bridge,file,{onConfirmed:proposal=>{const candidate=proposal.candidate||{},next={...savedDraft,invoice_mode:'recognition',invoice_code:candidate.invoice_code||'',invoice_number:candidate.invoice_number||'',invoice_date:candidate.issued_on||'',invoice_issuer_name:candidate.seller_name||'',invoice_amount:minorInput(candidate.total_amount_minor),amount:minorInput(candidate.total_amount_minor),business_date:candidate.issued_on||savedDraft.business_date,notice:'发票已确认并关联当前'+requestLabel+'；请核对信息后保存。'};if(type==='payment'&&next.payee_source==='one_time'&&!next.payee_name)next.payee_name=candidate.seller_name||'';openEditor(item,type,next,proposal)},onDismiss:()=>openEditor(item,type,{...savedDraft,notice:'已取消本次识别，'+requestLabel+'申请内容已保留。'},recognized)})}catch(error){openEditor(item,type,{...savedDraft,notice:error instanceof Error?error.message:'发票识别未完成'},recognized)}}}
    syncInvoice();
  }

  async function snapshot(ref,displayName){return {id:ref.id,revision:Number(ref.revision),digest:await hashSnapshot({id:ref.id,revision:Number(ref.revision),display_name:displayName}),display_name:displayName}}
  async function readDetails(form,type,item,recognized=null){
    const applicant=await snapshot(state.applicant,state.applicant.display_name),category=state.categories.find(value=>value.enabled&&value.key==='other')||state.categories.find(value=>value.enabled);
    if(!category)throw new Error('当前没有可用费用类别，请联系管理员');
    const existing=item?.details?.lines?.[0],evidence=Array.isArray(existing?.evidence)?existing.evidence.slice():[],invoiceMode=form.querySelector('[name="invoice_mode"]:checked')?.value||(item?'existing':'none'),file=form.querySelector('[name="finance_invoice_file"]')?.files?.[0];
    if(file){const bridge=globalThis.OMSPhase1EvidenceBridge;if(!bridge?.uploadFiles)throw new Error('发票上传功能暂不可用，请稍后重试');const status=form.querySelector('[data-oms-v1-form-status]'),refs=await bridge.uploadFiles([file],{ownerRef:'internal-finance-requests:'+(item?.id||'draft-'+uuid()),purpose:'invoice',status});evidence.splice(0,evidence.length,...refs.map(financeEvidenceRef))}
    const title=form.querySelector('[name="title"]').value.trim(),amountMinor=minorJSON(form.querySelector('[name="amount"]').value);let invoice=existing?.invoice||null;
    if(invoiceMode==='manual'){const invoiceAmount=minorJSON(form.querySelector('[name="invoice_amount"]').value),invoiceNumber=form.querySelector('[name="invoice_number"]').value.trim();if(!invoiceNumber)throw new Error('请填写发票号码');if(invoiceAmount!==amountMinor)throw new Error('申请金额必须与发票价税合计一致');invoice={code:form.querySelector('[name="invoice_code"]').value.trim(),number:invoiceNumber,issuer_name:form.querySelector('[name="invoice_issuer_name"]').value.trim(),invoice_date:form.querySelector('[name="invoice_date"]').value,amount_minor:invoiceAmount}}
    if(invoiceMode==='recognition'){if(!recognized||recognized.status!=='confirmed')throw new Error('请先完成发票识别并人工确认');const candidate=recognized.candidate||{},invoiceAmount=Number(candidate.total_amount_minor);if(!Number.isSafeInteger(invoiceAmount)||invoiceAmount<1||invoiceAmount!==amountMinor)throw new Error('申请金额必须与已确认发票价税合计一致');if(!recognized.evidence?.file_id||!recognized.evidence?.version)throw new Error('识别结果缺少原发票文件版本，不能关联');invoice={code:String(candidate.invoice_code||''),number:String(candidate.invoice_number||''),issuer_name:String(candidate.seller_name||''),invoice_date:String(candidate.issued_on||''),amount_minor:invoiceAmount};evidence.splice(0,evidence.length,{file_id:recognized.evidence.file_id,version:Number(recognized.evidence.version),purpose:'invoice',sha256:String(recognized.evidence.content_sha256||'').replace(/^sha256:/,''),media_type:String(recognized.evidence.mime_type||''),size_bytes:Number(recognized.evidence.size_bytes||0)})}
    if(invoiceMode==='none'){invoice=null;evidence.splice(0,evidence.length)}
    const line={id:existing?.id||form.dataset.lineId||uuid(),business_date:form.querySelector('[name="business_date"]').value,category_key:category.key,category_name:category.display_name,category_revision:Number(category.revision),purpose:title,amount_minor:amountMinor,evidence};if(invoice)line.invoice=invoice;const lines=[line];
    let payee={kind:'person',reference:applicant,display_name:applicant.display_name,bank_name:'',account_number:'',account_last4:'',delegate_reason:''};
    if(type==='payment'){const source=form.querySelector('[name="payee_source"]').value,name=form.querySelector('[name="payee_name"]').value.trim(),method=form.querySelector('[name="payment_method"]').value;payee={kind:source,entity_kind:'organization',display_name:name,payment_method:method,bank_name:method==='bank_transfer'?form.querySelector('[name="bank_name"]').value.trim():'',account_number:method==='bank_transfer'?form.querySelector('[name="account_number"]').value.replace(/[\s-]+/g,''):'',account_last4:''};if(source==='party'){const party=state.parties.find(value=>value.id===form.querySelector('[name="party_id"]').value);if(!party)throw new Error('请选择主体库收款方');payee.display_name=party.legal_name;payee.reference=await snapshot(party,party.legal_name)}}
    return {applicant,payee,lines,evidence:[],attribution:item?.details?.attribution||{},missing_evidence_acknowledged:false,approval:{policy:'not_required',status:'not_applicable',revision:1}};
  }
  function openEditor(item=null,requestedType='reimbursement',draft=null,recognized=null){
    const type=item?.request_type||requestedType,editorDraft=draftFromItem(item,draft);
    show({kicker:type==='payment'?'付款申请':'报销',title:item?'编辑'+(type==='payment'?'付款申请':'报销'):'新增'+(type==='payment'?'付款申请':'报销'),submit:item?'保存修改':'保存申请',enabled:Boolean(state.applicant),body:editorBody(item,type,editorDraft,recognized),onSubmit:async(_data,form)=>{const details=await readDetails(form,type,item,recognized),title=form.querySelector('[name="title"]').value.trim(),missing=!details.evidence.length&&!details.lines.some(line=>line.evidence?.length);if(type==='reimbursement'&&form.querySelector('[name="save_mode"]').value==='submit'&&missing)throw new Error('正式提交报销前请上传发票或其他有效凭证');let saved;if(item)saved=await put('/api/v1/finance-requests/'+encodeURIComponent(item.id),{command_id:uuid(),expected_revision:item.revision,title,amount_minor:1,details});else saved=await post('/api/v1/finance-requests',{command_id:uuid(),request_type:type,title,amount_minor:1,currency:'CNY',details});if(form.querySelector('[name="save_mode"]').value==='submit')try{saved=await post('/api/v1/finance-requests/'+encodeURIComponent(saved.id)+'/submit',{command_id:uuid(),expected_revision:saved.revision,missing_evidence_acknowledged:type==='payment'&&missing})}catch(error){if(error?.code==='INVOICE_STRONG_DUPLICATE'){await rememberStrongDuplicate(saved,error);close();openDuplicateResolution(saved);return}throw error}close();await load()}});
    queueMicrotask(()=>bindEditorControls(item,type,editorDraft,recognized));
  }

  function openDetail(item){
    const lines=item.details?.lines||[],payments=item.payments||[],attribution=item.details?.attribution||{},payee=item.details?.payee||{},cash=payee.payment_method==='cash',scope=[attribution.department&&'部门：'+attribution.department.display_name,attribution.project&&'项目：'+attribution.project.display_name,attribution.contract&&'合同：'+attribution.contract.display_name].filter(Boolean).join('；')||'未关联',conflict=duplicateSummary(item),conflictTarget=duplicateTarget(item);
    show({kicker:'财务申请',title:item.title,dismissOnly:true,body:'<section class="oms-v1__record-detail"><div class="oms-v1__record-status"><span>'+safe(typeLabels[item.request_type])+' · revision '+item.revision+'</span><strong>'+safe(statusLabels[item.status]||item.status)+'</strong></div>'+(conflict?'<div class="oms-v1__finance-conflict-panel"><strong>当前发票不能再次提交</strong><span>'+safe(conflict)+'</span>'+(conflictTarget?'<button type="button" data-open-duplicate-request="'+conflictTarget.id+'">查看占用申请</button>':'')+'</div>':'')+'<div class="oms-v1__record-metrics"><article class="is-primary"><span>申请总额</span><strong>'+model.money(item.amount_minor)+'</strong></article><article><span>累计实付</span><strong>'+model.money(item.paid_minor)+'</strong></article><article><span>已核销 / 剩余</span><strong>'+model.money(item.allocated_minor)+' / '+model.money(remaining(item))+'</strong></article></div><dl class="oms-v1__record-facts"><div><dt>申请人</dt><dd>'+safe(item.details?.applicant?.display_name||'—')+'</dd></div><div><dt>收款方</dt><dd>'+safe(payee.display_name||'—')+'</dd></div><div><dt>付款方式</dt><dd>'+safe(cash?'现金':payee.payment_method==='bank_transfer'?'银行卡':'—')+'</dd></div><div><dt>收款账号</dt><dd>'+safe(cash?'不适用':payee.account_last4?'尾号 '+payee.account_last4:'—')+'</dd></div><div><dt>费用归属</dt><dd>'+safe(scope)+'</dd></div><div><dt>审批策略</dt><dd>'+safe(item.approval_policy==='not_required'?'无需审批':'需要审批')+'</dd></div><div><dt>提交时间</dt><dd>'+dateTime(item.submitted_at)+'</dd></div><div><dt>更新时间</dt><dd>'+dateTime(item.updated_at)+'</dd></div></dl><div class="oms-v1__record-remark"><span>明细</span>'+lines.map(line=>'<p>'+safe(line.category_name||'付款用途')+' · '+safe(line.purpose)+' · '+model.money(line.amount_minor)+' · '+date(line.business_date)+(line.invoice?' · 发票 '+safe([line.invoice.code,line.invoice.number].filter(Boolean).join(' / ')||'已录入')+' · '+safe(line.invoice.issuer_name):'')+(line.evidence?.length?' · 原件 '+line.evidence.length+' 份':'')+'</p>').join('')+'</div>'+(payments.length?'<div class="oms-v1__record-remark"><span>付款记录</span>'+payments.map(value=>'<p>'+date(value.occurred_on)+' · 实付 '+model.money(value.actual_amount_minor)+' · 核销 '+model.money(value.allocated_amount_minor)+' · '+safe(value.status)+' · 操作人 '+safe(actorLabel(value.operator_subject_id))+(value.overage_amount_minor?' · 超额 '+model.money(value.overage_amount_minor)+'（'+safe(value.overage_reason||'未填写原因')+'）':'')+(value.money_payment_id?' · Money '+safe(value.money_payment_id):'')+'</p>').join('')+'</div>':'')+'<div class="oms-v1__row-actions">'+(!cash&&allowed(item,'read_sensitive_account')?'<button type="button" data-read-sensitive-account>查看完整账号</button>':'')+(submitSelectable(item)?'<button type="button" data-submit-single-request>提交申请</button>':'')+(paymentSelectable(item)?'<button type="button" data-confirm-single-payment>确认付款</button>':'')+(allowed(item,'delete')?'<button type="button" class="is-danger" data-delete-draft>删除草稿</button>':'')+'</div><div class="oms-v1__form-status" data-finance-detail-status></div></section>'});
    queueMicrotask(()=>{root.querySelector('[data-read-sensitive-account]')?.addEventListener('click',async()=>{const target=root.querySelector('[data-finance-detail-status]');try{const value=await api('/api/v1/finance-requests/'+encodeURIComponent(item.id)+'/sensitive-account?purpose='+encodeURIComponent('财务付款核对'));target.textContent='完整账号：'+value.details.payee.account_number}catch(error){target.textContent=error instanceof Error?error.message:'完整账号读取失败'}});root.querySelector('[data-open-duplicate-request]')?.addEventListener('click',()=>openDetail(conflictTarget));root.querySelector('[data-submit-single-request]')?.addEventListener('click',()=>{close();openSubmit([item])});root.querySelector('[data-confirm-single-payment]')?.addEventListener('click',()=>{close();openPayment([item])});root.querySelector('[data-delete-draft]')?.addEventListener('click',()=>openDelete(item))});
  }

  function openSubmit(items){
    const commands=new Map(items.map(item=>[item.id,uuid()]));
    show({
      kicker:'财务申请',
      title:items.length>1?'确认 '+items.length+' 笔进入待支付':'确认进入待支付',
      submit:'确认进入待支付',
      enabled:true,
      body:'<form class="oms-v1__form-grid"><section class="oms-v1__record-detail is-wide"><div class="oms-v1__record-remark"><span>即将进入待支付</span>'+items.map(item=>'<p>'+safe(typeLabels[item.request_type]||item.request_type)+' · '+safe(item.title)+' · '+model.money(item.amount_minor)+'</p>').join('')+'</div><p>确认后，草稿会变为待支付，但不会执行付款。报销必须已关联发票或其他有效凭证；付款申请缺少凭证时会按当前确认继续。</p></section>'+formStatus('')+'</form>',
      onSubmit:async()=>{
        for(const item of items){
          try{
            await post('/api/v1/finance-requests/'+encodeURIComponent(item.id)+'/submit',{command_id:commands.get(item.id),expected_revision:item.revision,missing_evidence_acknowledged:item.request_type==='payment'&&!hasEvidence(item)});
          }catch(error){
            if(error?.code==='INVOICE_STRONG_DUPLICATE'){
              await rememberStrongDuplicate(item,error);close();openDuplicateResolution(item);return;
            }
            if(isRevisionConflict(error)){
              const current=await api('/api/v1/finance-requests/'+encodeURIComponent(item.id)).catch(()=>null);
              if(hasEnteredPayable(current))continue;
              throw new Error(item.title+'：申请已被更新，请关闭窗口并重新确认');
            }
            throw new Error(item.title+'：'+(error instanceof Error?error.message:'进入待支付未完成'));
          }
        }
        state.selected.clear();close();await load();
      },
    });
  }

  function openPayment(items){const commands=new Map(items.map(item=>[item.id,uuid()])),batch=items.length>1,total=items.reduce((sum,item)=>sum+remaining(item),0n),rows=batch?'<div class="is-wide"><div class="oms-v1__record-remark"><span>逐笔确认 · 合计 '+model.money(total)+'</span>'+items.map(item=>'<div class="oms-v1__form-grid"><strong class="is-wide">'+safe(item.title)+' · 剩余 '+model.money(remaining(item))+'</strong>'+field('本次付款金额（元） *','<input name="amount_'+item.id+'" required inputmode="decimal" value="'+safe(minorInput(remaining(item)))+'">')+field('实际支付日期 *','<input name="date_'+item.id+'" type="date" required value="'+today()+'">')+field('超额原因','<input name="reason_'+item.id+'" maxlength="1000" placeholder="超额时必填">',true)+'</div>').join('')+'</div></div>':'';show({kicker:'财务付款',title:batch?'批量确认 '+items.length+' 笔':'确认实际付款',submit:'确认已支付',enabled:true,body:'<form class="oms-v1__form-grid">'+(batch?rows:field('实际付款金额（元） *','<input name="amount" required inputmode="decimal" value="'+safe(minorInput(remaining(items[0])))+'">')+field('实际支付日期 *','<input name="occurred_on" type="date" required value="'+today()+'">')+field('超额原因','<textarea name="overage_reason" maxlength="1000" placeholder="超额付款时必填"></textarea>',true))+field('付款说明','<input name="note" maxlength="500" value="已线下支付">')+'<div class="oms-v1__form-note is-wide">系统只登记已经发生的付款；Money 独立保存实际资金与整单核销。批量中的金额和日期逐笔确认，部分成功不会回滚其他成功记录。</div>'+formStatus('')+'</form>',onSubmit:async data=>{const note=String(data.get('note')||'').trim();let failed=[];if(!batch){const item=items[0],actual=minorJSON(data.get('amount')),overage=BigInt(actual)>remaining(item),reason=String(data.get('overage_reason')||'').trim();if(overage&&!reason)throw new Error('超额付款必须填写原因');await post('/api/v1/finance-requests/'+encodeURIComponent(item.id)+'/payments',{command_id:commands.get(item.id),expected_revision:item.revision,actual_amount_minor:actual,occurred_on:String(data.get('occurred_on')),note,overage_confirmed:overage,overage_reason:reason})}else{const entries=items.map(item=>{const actual=minorJSON(data.get('amount_'+item.id)),overage=BigInt(actual)>remaining(item),reason=String(data.get('reason_'+item.id)||'').trim();if(overage&&!reason)throw new Error(item.title+' 超额付款必须填写原因');return {request_id:item.id,command_id:commands.get(item.id),expected_revision:item.revision,actual_amount_minor:actual,occurred_on:String(data.get('date_'+item.id)),note,overage_confirmed:overage,overage_reason:reason}}),result=await post('/api/v1/finance-payments/batch',{items:entries});failed=(result.items||[]).filter(value=>value.error_code)}state.selected.clear();close();await load();if(failed.length)show({kicker:'财务付款',title:'批量付款结果',dismissOnly:true,body:'<section class="oms-v1__record-detail"><div class="oms-v1__record-status"><span>成功 '+(items.length-failed.length)+' 笔</span><strong>未完成 '+failed.length+' 笔</strong></div><div class="oms-v1__record-remark"><span>未完成项目</span>'+failed.map(value=>'<p>'+safe(items.find(item=>item.id===value.request_id)?.title||value.request_id)+' · '+safe(value.error_code)+' · '+safe(value.detail||'')+'</p>').join('')+'</div><p>已成功记录不会回滚；未知结果需按原命令恢复，确定失败项可重新发起。</p></section>'})}})}
  function openWithdraw(item){show({kicker:'财务申请',title:'撤回 '+item.title,submit:'确认撤回',enabled:true,body:'<form class="oms-v1__form-grid">'+field('撤回原因 *','<textarea name="reason" required maxlength="1000"></textarea>',true)+formStatus('')+'</form>',onSubmit:async data=>{await post('/api/v1/finance-requests/'+encodeURIComponent(item.id)+'/withdraw',{command_id:uuid(),expected_revision:item.revision,reason:String(data.get('reason')||'').trim()});close();await load()}})}
  function openDelete(item){show({kicker:'删除草稿',title:'删除 '+item.title,submit:'确认删除草稿',enabled:allowed(item,'delete'),body:'<form class="oms-v1__form-grid">'+field('删除原因 *','<textarea name="reason" required maxlength="1000" placeholder="例如：发票已在另一申请中提交"></textarea>',true)+'<div class="oms-v1__form-note is-wide">删除后不再出现在默认列表；系统仍保留删除时间、原因、操作人和凭证身份。已提交或已开始付款的申请不能删除。</div>'+formStatus(allowed(item,'delete')?'':'当前申请不允许删除')+'</form>',onSubmit:async data=>{const reason=String(data.get('reason')||'').trim();if(!reason)throw new Error('请填写删除原因');await del('/api/v1/finance-requests/'+encodeURIComponent(item.id),{command_id:uuid(),confirmation:'DELETE',reason});state.selected.delete(item.id);close();await load()}})}

  function categoryRow(item){const platform=item.source==='platform',nameControl=platform?'<input type="hidden" name="name_'+item.id+'" value="'+safe(item.display_name)+'"><strong>'+safe(item.display_name)+'</strong>':'<input class="oms-v1__category-name" name="name_'+item.id+'" value="'+safe(item.display_name)+'" maxlength="80" aria-label="类别名称">';return '<article class="oms-v1__category-row"><div class="oms-v1__category-identity">'+nameControl+'<small>'+safe(platform?'平台预置 · '+item.key:'自定义 · '+item.key)+'</small></div><label class="oms-v1__category-toggle"><input type="checkbox" name="enabled_'+item.id+'" '+(item.enabled?'checked':'')+'><span aria-hidden="true"></span><em class="is-on">已启用</em><em class="is-off">已停用</em></label></article>'}
  function openCategories(){const rows=state.categories.map(categoryRow).join('');show({kicker:'财务配置',title:'费用类别',submit:'保存设置',enabled:true,body:'<form class="oms-v1__form-grid oms-v1__category-form"><section class="oms-v1__category-editor is-wide"><header><div><strong>可用类别</strong><span>控制新增报销和付款申请可选择的类别</span></div><small>'+state.categories.filter(item=>item.enabled).length+' / '+state.categories.length+' 已启用</small></header><div class="oms-v1__category-list">'+rows+'</div></section><section class="oms-v1__category-create is-wide"><header><strong>新增自定义类别</strong><span>仅在确有独立统计口径时新增</span></header><div class="oms-v1__form-grid">'+field('类别标识','<input name="new_key" pattern="[a-z][a-z0-9_]{1,63}" placeholder="例如 client_gift">')+field('显示名称','<input name="new_name" maxlength="80" placeholder="例如 客户礼品费">')+'</div></section>'+field('变更原因 *','<input name="reason" required maxlength="200" value="财务类别维护">',true)+'<div class="oms-v1__form-note is-wide">平台预置类别只能启用或停用；历史申请继续保留提交时的类别快照。</div>'+formStatus('')+'</form>',onSubmit:async data=>{const reason=String(data.get('reason')||'').trim();for(const item of state.categories){const enabled=data.has('enabled_'+item.id),name=String(data.get('name_'+item.id)||item.display_name).trim();if(enabled!==item.enabled||name!==item.display_name)await put('/api/v1/expense-categories/'+item.id,{command_id:uuid(),expected_revision:item.revision,display_name:name,enabled,reason})}const key=String(data.get('new_key')||'').trim(),name=String(data.get('new_name')||'').trim();if(key||name){if(!key||!name)throw new Error('新增类别必须同时填写标识和名称');await post('/api/v1/expense-categories',{command_id:uuid(),key,display_name:name,reason})}close();await load()}})}

  function csvCell(value){let text=String(value??'');if(/^[=+\-@]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
  function saveCSV(name,rows){const blob=new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),0)}
  async function exportRecords(sensitive){const purpose=sensitive?String(globalThis.prompt('请输入敏感导出用途（将记录审计）','财务付款与审计核对')||'').trim():'';if(sensitive&&!purpose)return;const payload=await api(sensitive?'/api/v1/finance-request-sensitive-exports?purpose='+encodeURIComponent(purpose):'/api/v1/finance-request-exports'),items=filtered(Array.isArray(payload.items)?payload.items:[]),headers=['申请 ID','类型','事项','申请人','申请人 ID','收款方','付款方式','收款账号','总额（元）','已付（元）','已核销（元）','超额（元）','状态','业务日期','费用承担部门','关联项目','关联合同','最新操作人','更新时间'],rows=[headers,...items.map(item=>[item.id,typeLabels[item.request_type]||item.request_type,item.title,item.details?.applicant?.display_name,item.applicant_subject_id,item.details?.payee?.display_name,item.details?.payee?.payment_method==='cash'?'现金':item.details?.payee?.payment_method==='bank_transfer'?'银行卡':'',item.details?.payee?.payment_method==='cash'?'':sensitive?item.details?.payee?.account_number:(item.details?.payee?.account_last4?'尾号 '+item.details.payee.account_last4:''),minorInput(item.amount_minor),minorInput(item.paid_minor),minorInput(item.allocated_minor),minorInput(item.overage_minor),statusLabels[item.status]||item.status,item.details?.lines?.[0]?.business_date||'',item.details?.attribution?.department?.display_name||'',item.details?.attribution?.project?.display_name||'',item.details?.attribution?.contract?.display_name||'',actorLabel(item.payments?.at(-1)?.operator_subject_id||item.applicant_subject_id),item.updated_at])];if(sensitive)rows.unshift(['敏感数据：包含完整收款账号','导出用途：'+purpose]);saveCSV((sensitive?'财务申请-敏感-':'财务申请-')+today()+'.csv',rows)}

  const listActions=root.querySelector('[data-internal-new-finance]')?.parentElement;
  if(listActions){const categories=document.createElement('button'),exportButton=document.createElement('button'),sensitiveExport=document.createElement('button');for(const button of [categories,exportButton,sensitiveExport]){button.type='button';button.className='oms-v1__export'}categories.textContent='类别设置';categories.dataset.internalFinanceCategories='';exportButton.textContent='导出';exportButton.dataset.internalFinanceExport='';sensitiveExport.textContent='敏感导出';sensitiveExport.dataset.internalFinanceSensitiveExport='';listActions.prepend(categories,exportButton,sensitiveExport);categories.onclick=openCategories;exportButton.onclick=()=>exportRecords(false).catch(error=>globalThis.alert(error instanceof Error?error.message:'导出失败'));sensitiveExport.onclick=()=>exportRecords(true).catch(error=>globalThis.alert(error instanceof Error?error.message:'敏感导出失败'))}
  for(const button of root.querySelectorAll('[data-internal-new-finance]'))button.onclick=()=>openEditor(null,button.dataset.internalNewFinance||'reimbursement');
  root.querySelector('[data-internal-finance-paid]').onclick=()=>{const items=state.items.filter(item=>state.selected.has(item.id));selectedBatchKind()==='submit'?openSubmit(items):openPayment(items)};
  root.querySelector('[data-internal-finance-select-all]').onclick=()=>{const items=filtered(),mode=selectedBatchKind()||batchKind(items.find(item=>batchKind(item)));for(const item of items)if(batchKind(item)===mode)state.selected.add(item.id);render()};
  root.querySelector('[data-internal-finance-clear]').onclick=()=>{state.selected.clear();render()};
  root.querySelector('[data-internal-finance-search]').oninput=()=>{state.page=1;state.selected.clear();render()};
  for(const select of root.querySelectorAll('[data-internal-finance-type],[data-internal-finance-status]'))select.onchange=()=>{state.page=1;state.selected.clear();render()};
  void load();
})();
